DROP TABLE IF EXISTS `answer_detail`;
CREATE TABLE `answer_detail`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `paper_id` bigint NOT NULL COMMENT '试卷ID',
  `user_id` bigint NOT NULL COMMENT '答题人ID',
  `exam_send_id` bigint NULL DEFAULT NULL COMMENT '考试发放记录ID',
  `question_id` bigint NOT NULL COMMENT '题目ID',
  `record_id` bigint NOT NULL COMMENT '考试记录ID',
  `user_answer` text CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL COMMENT '考生答题内容',
  `ok_flag` tinyint(1) NULL DEFAULT NULL COMMENT '是否正确（0-错误 1-正确, 2.待批改）',
  `score` decimal(5, 2) NULL DEFAULT NULL COMMENT '得分',
  `user_answer_version` int NULL DEFAULT NULL COMMENT '答题版本',
  `submit_time` datetime NULL DEFAULT NULL COMMENT '提交时间',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `create_user_id` bigint NULL DEFAULT NULL COMMENT '创建人ID',
  `update_user_id` bigint NULL DEFAULT NULL COMMENT '更新人ID',
  `del_flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT '0' COMMENT '删除标识（0：未删除，2：已删除）',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_exam_send_id`(`exam_send_id` ASC) USING BTREE,
  INDEX `idx_user_id`(`user_id` ASC) USING BTREE,
  INDEX `idx_question_id`(`question_id` ASC) USING BTREE,
  INDEX `idx_submit_time`(`submit_time` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1903481464256278535 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_bin COMMENT = '答题详情' ROW_FORMAT = Dynamic;

