INSERT INTO `answer_detail` VALUES (1902900826763472898, 1901802974431727618, 1, 1901803309606948865, 1900163098019909642, 1901803309606948866, 'def is_prime(n):\n    if n < 2:\n        return False\n    for i in range(2, int(n ** 0.5) + 1):\n        if n % i == 0:\n            return False\n    return True', 2, 0.00, NULL, NULL, '2025-03-21 09:51:26', '2025-03-21 09:51:25', 1, NULL, '0');
