INSERT INTO `answer_detail` VALUES (1902909805572919301, 1901548977405935617, 1, 1901551534140407809, 1900024401161278887, 1901551534140407811, '    public int fibonacci(int n) {\n        if (n <= 0) {\n            throw new IllegalArgumentException(\"输入必须是正整数\");\n        }\n        if (n == 1 || n == 2) {\n            return 1;\n        }\n        return fibonacci(n - 1) + fibonacci(n - 2);\n    }', 3, 9.50, NULL, NULL, '2025-03-21 10:27:07', '2025-03-21 10:38:42', 1, 1, '0');
