INSERT INTO `answer_detail` VALUES (1902918071518498821, 1901546936809930753, 1, 1901557998972116994, 1900024401161278887, 1901557999014060035, 'public class Fibonacci {\n    public static int fibonacci(int n) {\n        if (n <= 0) {\n            throw new IllegalArgumentException(\"n 必须是正整数\");\n        }\n        if (n == 1 || n == 2) {\n            return 1;\n        }\n        return fibonacci(n - 1) + fibonacci(n - 2);\n    }\n\n    public static void main(String[] args) {\n        int n = 10; // 计算第 10 项的斐波那契数\n        System.out.println(\"斐波那契数列第 \" + n + \" 项: \" + fibonacci(n));\n    }\n}', 1, 10.00, NULL, NULL, '2025-03-21 10:59:57', '2025-03-21 15:39:40', 1, 1, '0');
