INSERT INTO `question` VALUES (01900163098019909641, 4, 4, '世界上最长的河流是__？', '\"\\\"[]\\\"\"', '尼罗河', 1, '尼罗河是世界上最长的河流，全长约 6650 公里。', 5.00, '2025-03-14 08:27:50', '2025-03-14 08:27:50', 1, 1, '0');
INSERT INTO `question` VALUES (01900163098019909642, 5, 5, '请写一个 Python 代码，判断一个数是否是素数', '[]', 'def is_prime(n):\n    if n < 2:\n        return False\n    for i in range(2, int(n**0.5) + 1):\n        if n % i == 0:\n            return False\n    return True', NULL, '判断素数的基本方法是除以从 2 到 sqrt(n) 之间的所有整数。', 10.00, '2025-03-14 08:27:50', '2025-03-14 17:15:03', 1, 1, '0');
INSERT INTO `question` VALUES (01900163098019909643, 1, 1, '下列哪位不是唐代诗人？', '[{\"option\": \"A\", \"content\": \"杜甫\"}, {\"option\": \"B\", \"content\": \"白居易\"}, {\"option\": \"C\", \"content\": \"苏轼\"}, {\"option\": \"D\", \"content\": \"李白\"}]', 'C', NULL, '苏轼是宋代诗人，而杜甫、白居易、李白都是唐代诗人。', 4.00, '2025-03-14 08:27:50', '2025-03-20 17:28:10', 1, 1, '0');
INSERT INTO `question` VALUES (01900163098019909644, 2, 2, '以下哪些属于三角函数？', '[{\"option\": \"A\", \"content\": \"sin\"}, {\"option\": \"B\", \"content\": \"cos\"}, {\"option\": \"C\", \"content\": \"tan\"}, {\"option\": \"D\", \"content\": \"log\"}]', 'A|B|C', NULL, 'sin、cos、tan 是基本的三角函数，而 log 是对数函数。', 7.00, '2025-03-14 08:27:50', '2025-03-14 08:27:50', 1, NULL, '0');
INSERT INTO `question` VALUES (01900163098019909645, 3, 3, '企鹅能在水中游泳，对吗？', '[{\"option\": \"A\", \"content\": \"正确\"}, {\"option\": \"B\", \"content\": \"错误\"}]', 'A', NULL, '企鹅不会飞，但它们是出色的游泳高手。', 3.00, '2025-03-14 08:27:50', '2025-03-20 17:28:25', 1, 1, '0');
INSERT INTO `question` VALUES (01900163098019909646, 4, 4, '太阳系中最接近太阳的行星是__？', '\"\\\"[]\\\"\"', '水星', 1, '水星是距离太阳最近的行星，公转周期约为 88 天。', 5.00, '2025-03-14 08:27:50', '2025-03-14 08:27:50', 1, 1, '0');
INSERT INTO `question` VALUES (01902974344398110721, 2, 2, '以下哪些是 Java 的基本数据类型？？？？', '[{\"option\": \"A\", \"content\": \"int\"}, {\"option\": \"B\", \"content\": \"double\"}, {\"option\": \"C\", \"content\": \"String\"}, {\"option\": \"D\", \"content\": \"boolean\"}]', 'A|B|D', NULL, 'Java 的基本数据类型包括 int、double、boolean 等，String 是对象类型。', 6.00, '2025-03-21 14:43:34', '2025-03-21 15:36:14', 1, NULL, '0');
INSERT INTO `question` VALUES (01902983536945143809, 1, 1, '以下哪个国家的首都是伦敦？？？？？？', '[{\"option\": \"A\", \"content\": \"法国\"}, {\"option\": \"B\", \"content\": \"英国\"}, {\"option\": \"C\", \"content\": \"德国\"}, {\"option\": \"D\", \"content\": \"西班牙\"}]', 'B', NULL, '英国的首都是伦敦。', 4.00, '2025-03-21 15:20:06', '2025-03-24 16:30:21', 1, 1, '0');
INSERT INTO `question` VALUES (01904088251682590722, 1, 1, '洒', '[{\"option\": \"A\", \"content\": \"撒擦电视\"}, {\"option\": \"B\", \"content\": \"川师大\"}, {\"option\": \"C\", \"content\": \"吃撒的\"}, {\"option\": \"D\", \"content\": \"山财大\"}]', 'C', NULL, 'csac', 2.00, '2025-03-24 16:29:50', '2025-03-24 16:29:53', 1, 1, '0');
